      var g = font.glyphs[ch];
      for (var row = 0; row < g[1]; row += 1) {
        for (var col = 0; col < g[0]; col += 1) {
          if (g[5][row] & (1 << col)) {
            ctx.fillRect(x + g[2] + col, y + g[3] + row, 1, 1);
          }
        }
      }
      x += g[4];
    });
  }

  function draw(canvas, settings, platform, pageIndex) {
