    var geo = layout.geometry(settings, platform);
    var pages = layout.paginate([sample.replace(/^16\. /, "")], settings, platform, 16);
    pages.pages[Math.min(pageIndex || 0, pages.pages.length - 1)].split("\n").forEach(function(line, index) {
